create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key default gen_random_uuid(),name text not null,name_key text unique not null,pin_hash text not null,role text not null default 'candidate',status text not null default 'pending',created_at timestamptz default now());
create table if not exists documents(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references profiles(id) on delete cascade,file_name text not null,storage_path text not null,status text not null default 'pending',review_note text,reviewed_by uuid references profiles(id),reviewed_at timestamptz,created_at timestamptz default now());
create table if not exists exams(id uuid primary key default gen_random_uuid(),title text not null,description text,status text not null default 'draft',starts_at timestamptz,ends_at timestamptz,passing_percent numeric not null default 60,time_limit_minutes int, max_attempts int not null default 1,created_by uuid references profiles(id),created_at timestamptz default now());
create table if not exists questions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references exams(id) on delete cascade,statement text not null,image_url text,points numeric not null default 1,order_index int not null default 0);
create table if not exists alternatives(id uuid primary key default gen_random_uuid(),question_id uuid not null references questions(id) on delete cascade,text text not null,order_index int not null default 0,is_correct boolean not null default false);
create table if not exists attempts(id uuid primary key default gen_random_uuid(),exam_id uuid not null references exams(id),candidate_id uuid not null references profiles(id),score numeric not null default 0,max_score numeric not null default 0,passed boolean not null default false,created_at timestamptz default now());
create unique index if not exists attempts_candidate_exam_once on attempts(candidate_id,exam_id);
create table if not exists answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references attempts(id) on delete cascade,question_id uuid not null references questions(id),alternative_id uuid references alternatives(id));
create table if not exists cnd(id uuid primary key default gen_random_uuid(),candidate_id uuid unique not null references profiles(id),number text unique not null,issued_at timestamptz default now(),status text default 'active');
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text not null,target_type text,target_id uuid,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
alter table exams add column if not exists passing_percent numeric not null default 60;
alter table exams add column if not exists time_limit_minutes int;
alter table exams add column if not exists max_attempts int not null default 1;
alter table profiles enable row level security;alter table documents enable row level security;alter table exams enable row level security;alter table questions enable row level security;alter table alternatives enable row level security;alter table attempts enable row level security;alter table answers enable row level security;alter table cnd enable row level security;alter table audit_logs enable row level security;
insert into storage.buckets(id,name,public) values('documents','documents',false) on conflict(id) do nothing;